#!/usr/bin/env python3
"""Validate DDLC/Katawa CPython 3.15 bundles generated by CMake or Xcode."""
from __future__ import annotations

import argparse
import plistlib
import sys
from pathlib import Path


def check_bundle(bundle: Path, platform: str) -> None:
    if bundle.suffix != ".app" or not bundle.is_dir():
        raise ValueError(f"Not an application bundle: {bundle}")
    contents = bundle / "Contents" if platform == "macos" else bundle
    info = contents / "Info.plist"
    if not info.is_file():
        raise ValueError(f"Missing Info.plist: {info}")
    with info.open("rb") as stream:
        metadata = plistlib.load(stream)
    identifier = metadata.get("CFBundleIdentifier", "")
    if not identifier:
        raise ValueError(f"No CFBundleIdentifier: {info}")

    binary = contents / "Frameworks" / "Python.framework" / "Python"
    if not binary.is_file():
        raise ValueError(f"Missing embedded Python.framework binary: {binary}")
    if platform == "macos":
        versions = binary.parent / "Versions"
        homes = [versions / "Current", *sorted(versions.glob("*"))]
        stdlib_files = [
            home / "lib" / "python3.15" / "encodings" / "__init__.py"
            for home in homes
        ]
        if not any(path.is_file() for path in stdlib_files):
            raise ValueError(
                "Missing CPython 3.15 standard library inside Python.framework"
            )
    else:
        stdlib = (
            contents / "python" / "lib" / "python3.15"
            / "encodings" / "__init__.py"
        )
        if not stdlib.is_file():
            raise ValueError(f"Missing iOS CPython 3.15 standard library: {stdlib}")
    print(f"OK: {bundle} ({platform}) | {identifier} | CPython 3.15 bundled")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("app", type=Path, help="Path to DDLC or Katawa .app")
    parser.add_argument("--platform", choices=("macos", "ios"), required=True)
    args = parser.parse_args()
    try:
        check_bundle(args.app.resolve(), args.platform)
    except (OSError, ValueError, plistlib.InvalidFileException) as error:
        print(f"ERROR: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
